// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Data set instance.
*/
interface DataSet {
	/**
	* Serializes an instance to a JSON object.
	*
	* @returns JSON object
	*/
	toJSON(): object;
}

/**
* Converts an array of objects to a "tidy" data set.
*
* @param arr - input array
* @param name - data set name
* @param mapping - object mapping existing field names to new field names
* @returns data set instance
*
* @example
* var x = [
*     {
*         'a': 1,
*         'b': 2
*     },
*     {
*         'a': 3,
*         'b': 4
*     }
* ];
*
* var mapping = {
*     'a': 'x',
*     'b': 'y'
* };
* var v = objarray2tidy( x, 'data', mapping );
* // returns <DataSet>
*/
declare function objarray2tidy( arr: Collection<object>, name: string, mapping?: Record<string, string> ): DataSet;


// EXPORTS //

export = objarray2tidy;
